"""Conversion between currencies."""

from decimal import ROUND_HALF_UP, Decimal, localcontext

from fxquote.rates import RateError, RateTable

MINOR_UNITS = {"JPY": 0, "KRW": 0, "KWD": 3, "BHD": 3}

_PRECISION = 60


def _round_to_minor_unit(amount: Decimal, code: str) -> Decimal:
    exponent = -MINOR_UNITS.get(code, 2)
    with localcontext() as ctx:
        ctx.prec = _PRECISION
        rounded = amount.quantize(Decimal(1).scaleb(exponent), rounding=ROUND_HALF_UP)
    return rounded if rounded else abs(rounded)


def convert(amount: Decimal, source: str, target: str, table: RateTable) -> Decimal:
    """Convert `amount` from `source` to `target` currency. See README.md for the rules."""
    try:
        source_rate = table.rates[source]
        target_rate = table.rates[target]
    except KeyError as exc:
        raise RateError(f"no rate for currency {exc.args[0]!r}") from None
    with localcontext() as ctx:
        ctx.prec = _PRECISION
        converted = amount * target_rate / source_rate
    return _round_to_minor_unit(converted, target)


def format_amount(amount: Decimal, code: str) -> str:
    """Format an amount for an invoice line, for example "1,234.50 USD"."""
    return f"{_round_to_minor_unit(amount, code):,f} {code}"

"""Reference rates published by the treasury rate service."""

import http.client
import json
import re
import urllib.parse
import urllib.request
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation

RATES_URL = "https://fx.treasury.internal/v1/rates"

_CODE = re.compile(r"[A-Z]{3}")


def _check_code(code: object) -> str:
    if not isinstance(code, str) or not _CODE.fullmatch(code):
        raise RateError(f"invalid currency code: {code!r}")
    return code


def _parse_rate(code: str, value: object) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (str, int, Decimal)):
        raise RateError(f"invalid rate for {code}: {value!r}")
    try:
        rate = Decimal(value)
    except (InvalidOperation, ValueError):
        raise RateError(f"invalid rate for {code}: {value!r}") from None
    if not rate.is_finite() or rate <= 0:
        raise RateError(f"invalid rate for {code}: {value!r}")
    return rate


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        data = json.loads(text, parse_float=Decimal)
    except (TypeError, ValueError) as exc:
        raise RateError(f"rate payload is not valid JSON: {exc}") from None
    if not isinstance(data, dict):
        raise RateError("rate payload must be a JSON object")
    if "base" not in data:
        raise RateError("rate payload has no base")
    base = _check_code(data["base"])
    as_of = data.get("as_of")
    if not isinstance(as_of, str):
        raise RateError("rate payload has no as_of string")
    raw = data.get("rates")
    if not isinstance(raw, dict):
        raise RateError("rate payload has no rates object")
    rates = {code: _parse_rate(_check_code(code), value) for code, value in raw.items()}
    rates[base] = Decimal(1)
    return RateTable(base=base, as_of=as_of, rates=rates)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    _check_code(base)
    url = f"{RATES_URL}?{urllib.parse.urlencode({'base': base})}"
    try:
        with urllib.request.urlopen(url, timeout=timeout) as response:
            if response.status != 200:
                raise RateError(f"rate service unavailable: HTTP {response.status}")
            body = response.read().decode("utf-8")
    except (OSError, http.client.HTTPException, UnicodeDecodeError) as exc:
        raise RateError(f"rate service unavailable: {exc}") from exc
    return parse_rates(body)
